export type GameAction = { "game": "bang", "payload": Action } | { "game": "uno", "payload": UnoAction } | { "game": "werewolf", "payload": WerewolfAction } | { "game": "cats", "payload": CatsAction };

export type GameDelta = { "game": "bang", events: BangEvents, view: BangView, } | { "game": "uno", events: UnoEvents, view: UnoView, } | { "game": "werewolf", events: WerewolfEvents, view: WerewolfView, } | { "game": "cats", events: CatsEvents, view: CatsView, };

export type ErrorCode = "unsupported_version" | "invalid_message" | "room_not_found" | "nickname_taken" | "invalid_nickname" | "invalid_token" | "already_in_room" | "not_in_room" | "not_host" | "wrong_phase" | "not_enough_players" | "no_free_seat" | "server_busy" | "illegal_action" | "invalid_settings" | "game_unavailable";

export type Phase = "waiting" | "playing";

export type Role = "player" | "spectator";

export type Member = { id: string, nickname: string, role: Role, online: boolean, };

export type GameKind = "bang" | "uno" | "werewolf" | "cats";

export type RoomView = { game: GameKind, settings: GameSettings, code: string, phase: Phase, host: string, you: string, min_players: number, max_players: number, members: Array<Member>, };

export type VoiceError = "voice_disabled" | "not_in_room" | "voice_unavailable" | "rate_limited";

export type VoiceTokenResult = { "status": "ok", url: string, token: string, expires_at: number, } | { "status": "error", code: VoiceError, };

export type ClientMessage = { "type": "ping", v: number, nonce: number, } | { "type": "voice_token", v: number, nonce: number, } | { "type": "voice_leave", v: number, nonce: number, } | { "type": "create_room", v: number, nickname: string, game: GameKind, } | { "type": "join_room", v: number, room_code: string, nickname: string, } | { "type": "rejoin_room", v: number, room_code: string, token: string, } | { "type": "leave_room", v: number, } | { "type": "take_seat", v: number, } | { "type": "change_game", v: number, game: GameKind, } | { "type": "start_game", v: number, } | { "type": "update_settings", v: number, settings: GameSettings, } | { "type": "game_action", v: number, action: GameAction, } | { "type": "host_skip", v: number, } | { "type": "end_game", v: number, };

export type ServerMessage = { "type": "game_started", v: number, seq: number, seats: Array<GameSeat>, view: GameView, } | { "type": "game_update", v: number, seq: number, update: GameDelta, } | { "type": "game_over", v: number, seq: number, update: GameDelta, } | { "type": "joined", v: number, room_code: string, token: string, room: RoomView, game: GameSnapshot | null, voice_enabled: boolean, } | { "type": "room_state", v: number, room: RoomView, } | { "type": "left", v: number, } | { "type": "pong", v: number, nonce: number, } | { "type": "voice_token_result", v: number, nonce: number, result: VoiceTokenResult, } | { "type": "voice_leave_result", v: number, nonce: number, error: VoiceError | null, } | { "type": "error", v: number, code: ErrorCode, message: string, };
